  /// the Prashna lagna. topic: career, financial, health, litigation, marriage,
  /// missing_person, property or travel; or questionHouse 1-12 when topic is
  /// not given (with neither, only the lagna and Moon sections). An unknown
  /// topic or a house outside 1-12 returns 400.
  ///
  /// `GET /v1/vedic/narrative/prashna`
  Future<T> prashna<T>({
    required num lat,
    required num lon,
    required String tz,
    String? date,
    String? time,
    Ayanamsa? ayanamsa,
    String? topic,
    int? questionHouse,
    Lang? lang,
    RequestOptions? options,
  }) {
    final $q = <String, Object?>{}
      ..put('lat', lat)
      ..put('lon', lon)
      ..put('tz', tz)
      ..put('date', date ?? todayIn(tz))
      ..put('time', time)
      ..put('ayanamsa', ayanamsa?.wire)
      ..put('topic', topic)
      ..put('question_house', questionHouse)
      ..put('lang', lang?.code)
      ..put('locale', lang?.code);
    return _c.request<T>('/v1/vedic/narrative/prashna', $q, options);
  }

